                if dataset.startswith('hardware'):
                    assert info['audio_sha256']==entry['audio_sha256'];audit['captures'][str(audio.relative_to(ROOT))]=info
                else:audit['files'].setdefault(n,{})[mode]=info
    # Reusable metric extraction must preserve full stream output, including state.
