from analysis import *
from scipy.optimize import minimize
from scipy.special import logsumexp
def group(n):
    if n.startswith('libri_'):return n.split('_')[1].split('-')[0]
    if n.startswith('arctic_'):return n.split('_')[1]
    return '_'.join(n.split('_')[:2])
def features(trace):
    rows=[]
    for t in trace:
        rho=np.array(t['band_periodicity']);weight=np.array(t['band_weight']);b1=t['old_b1']
        rows.append(np.r_[rho,weight,np.log(np.maximum(weight,1e-4)),t['old_b0']/119,MIX[b1],np.eye(16)[b1]])
    return np.array(rows)
def fit(x,y):
    mean=x.mean(axis=0);scale=x.std(axis=0);scale[scale<1e-4]=1
    x=np.c_[np.ones(len(x)),(x-mean)/scale];target=np.eye(16)[y];reg=.003
    def objective(flat):
        w=flat.reshape(x.shape[1],16);logits=x@w;normal=logsumexp(logits,axis=1)
        loss=np.mean(normal-logits[np.arange(len(y)),y])+.5*reg*np.sum(w[1:]**2)
        probabilities=np.exp(logits-normal[:,None]);gradient=x.T@(probabilities-target)/len(x);gradient[1:]+=reg*w[1:]
        return loss,gradient.ravel()
    r=minimize(objective,np.zeros(x.shape[1]*16),jac=True,method='L-BFGS-B',options={'maxiter':500,'ftol':1e-8})
    if not r.success:raise RuntimeError(r.message)
    return {'mean':mean.tolist(),'scale':scale.tolist(),'weights':r.x.reshape(x.shape[1],16).tolist(),'iterations':r.nit,'regularisation':reg}
def predict(model,x,old):
    x=np.c_[np.ones(len(x)),(x-np.array(model['mean']))/np.array(model['scale'])]
    logits=x@np.array(model['weights']);p=np.exp(logits-logsumexp(logits,axis=1)[:,None]);best=np.argmax(p,axis=1)
    # Fixed conservative confidence gate, specified before quality scoring.
    change=(p[np.arange(len(x)),best]>.65)&((p[np.arange(len(x)),best]-p[np.arange(len(x)),old])>.35)
    return np.where(change,best,old),p
def encode(n,chosen,input_dir):
    path=OUT/f'{n}.learned_voice.model';lines=[]
    for row,b1 in zip((MODELS/f'{n}.energy_grid.model').read_text().splitlines(),chosen):
        v=row.split();v[1]=str(b1);lines.append(' '.join(v)+'\n')
    path.write_text(''.join(lines));indices=OUT/f'{n}.learned_voice.indices';frames=OUT/f'{n}.learned_voice.dvsi';audio=OUT/f'{n}.learned_voice.wav'
    run(ENCODE,path,indices);run(BASE,'frames','--rate','dstar',indices,frames);run(BASE,'decode','--rate','dstar',frames,audio)
    return {**score(read_wav(input_dir/f'{n}.wav'),read_wav(audio),None),'frames_sha256':hashlib.sha256(frames.read_bytes()).hexdigest()}
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--manifest',type=Path);ap.add_argument('--input-dir',type=Path,default=ROOT/'testdata/corpus');a=ap.parse_args()
    validation=bool(a.manifest)
    names=[r['name'] for r in json.loads(a.manifest.read_text())['files']] if validation else list(json.loads((OUT/'analysis-full.json').read_text())['files'])
    data={};provenance={}
    for n in names:
        trace=json.loads((OUT/f'{n}.analysis.json').read_text());x=features(trace);old=np.array([t['old_b1'] for t in trace])
        if validation:y=None
        else:
            gold=ROOT/f'corpus/golden/dstar/{n}.dvsi';parms=OUT/f'{n}.gold.parms';run(BASE,'parms','--rate','dstar',gold,parms)
            fields=[list(map(int,line.split()[:9])) for line in parms.read_text().splitlines()];assert len(fields)==len(x)
            y=np.array([v[1] if v[0]<120 and 0<=v[1]<16 else -1 for v in fields]);provenance[n]=hashlib.sha256(gold.read_bytes()).hexdigest()
        data[n]=(x,old,y)
    predictions={};models={}
    if validation:
        model=json.loads((OUT/'voicing-model.json').read_text())
        for n,(x,old,_) in data.items():predictions[n]=predict(model,x,old)[0]
    else:
        for g in sorted(set(map(group,names))):
            train=[(x,y) for n,(x,_,y) in data.items() if group(n)!=g];x=np.concatenate([x[y>=0] for x,y in train]);y=np.concatenate([y[y>=0] for _,y in train])
            model=fit(x,y);models[g]=model
            for n,(x,old,y) in data.items():
                if group(n)==g:predictions[n]=predict(model,x,old)[0]
            print('fit excluded group',g,flush=True)
        x=np.concatenate([x[y>=0] for x,_,y in data.values()]);y=np.concatenate([y[y>=0] for _,_,y in data.values()])
        (OUT/'voicing-model.json').write_text(json.dumps(fit(x,y),indent=2))
    report={'files':{},'classification':{},'fold_models':models,'golden_hashes':provenance}
    controls=json.loads((OUT/('analysis-validation.json' if validation else 'analysis-full.json')).read_text())['files']
    for n in names:
        x,old,y=data[n];chosen=predictions[n]
        report['classification'][n]={'changed_frames':int(np.count_nonzero(chosen!=old)),'frames':len(x)}
        if y is not None:
            mask=y>=0;report['classification'][n].update({'baseline_correct':int(np.sum(old[mask]==y[mask])),'candidate_correct':int(np.sum(chosen[mask]==y[mask])),'labelled':int(mask.sum())})
        row={'base':controls[n]['base'],'energy':controls[n]['energy'],'learned_voice':encode(n,chosen,a.input_dir)};report['files'][n]=row
        report['summary']=summaries(report['files'],['learned_voice']);report['versus_float']=summaries(report['files'],['learned_voice'],'energy')
        (OUT/('learned-validation.json' if validation else 'learned-cv.json')).write_text(json.dumps(report,indent=2))
        print(n,round(row['learned_voice']['pesq']-row['energy']['pesq'],3),flush=True)
    print(json.dumps(report['versus_float'],indent=2))

